SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['4f5ffc62-ebdf-4768-a11c-7dd384c3c6d7','c83aac5f-eba3-49da-baab-cbef76e8bc6e']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['4f5ffc62-ebdf-4768-a11c-7dd384c3c6d7','c83aac5f-eba3-49da-baab-cbef76e8bc6e']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['4f5ffc62-ebdf-4768-a11c-7dd384c3c6d7','c83aac5f-eba3-49da-baab-cbef76e8bc6e']::uuid[]) OR variant_id=ANY(ARRAY['95aea58b-127f-4b66-9906-2c4f2ad8763f','b685e065-7995-4968-bc77-67826c3245fe']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['151b0439-551d-49d6-bd35-32c4d3a2de4f']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['4f5ffc62-ebdf-4768-a11c-7dd384c3c6d7','c83aac5f-eba3-49da-baab-cbef76e8bc6e']::uuid[]) OR variant_id=ANY(ARRAY['95aea58b-127f-4b66-9906-2c4f2ad8763f','b685e065-7995-4968-bc77-67826c3245fe']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['151b0439-551d-49d6-bd35-32c4d3a2de4f']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['4f5ffc62-ebdf-4768-a11c-7dd384c3c6d7','c83aac5f-eba3-49da-baab-cbef76e8bc6e']::uuid[]) OR variant_id=ANY(ARRAY['95aea58b-127f-4b66-9906-2c4f2ad8763f','b685e065-7995-4968-bc77-67826c3245fe']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['4f5ffc62-ebdf-4768-a11c-7dd384c3c6d7','c83aac5f-eba3-49da-baab-cbef76e8bc6e']::uuid[]) OR variant_id=ANY(ARRAY['95aea58b-127f-4b66-9906-2c4f2ad8763f','b685e065-7995-4968-bc77-67826c3245fe']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['151b0439-551d-49d6-bd35-32c4d3a2de4f']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['151b0439-551d-49d6-bd35-32c4d3a2de4f']::uuid[])) ORDER BY scope,identity;